IntroAssets write_intro_assets(const std::string& dir) {
    namespace fs = std::filesystem;
    fs::create_directories(dir);
    fs::path play = fs::path(dir) / "play.png";
    fs::path cursor = fs::path(dir) / "cursor.png";
    write_blob(play, kPlayPng, kPlayPng_len);
    write_blob(cursor, kCursorPng, kCursorPng_len);
    return {play.string(), cursor.string()};
}

